import products from './products.json' with { type: 'json' };

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory by product name',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query for product name' },
          limit: { type: 'integer', description: 'Maximum number of results (1-10)', minimum: 1, maximum: 10 }
        },
        required: ['query']
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate required 'query'
  if (typeof args.query !== 'string' || args.query.trim() === '') {
    throw new Error('Invalid arguments: query must be a non-empty string');
  }

  // Validate optional 'limit'
  let limit = 10;
  if (args.limit !== undefined) {
    if (typeof args.limit !== 'number' || !Number.isInteger(args.limit) || args.limit < 1 || args.limit > 10) {
      throw new Error('Invalid arguments: limit must be an integer between 1 and 10');
    }
    limit = args.limit;
  }

  const query = args.query.toLowerCase();

  // Case-insensitive search
  const matches = products.filter(p => p.name.toLowerCase().includes(query));

  // Apply limit
  const results = matches.slice(0, limit);

  const text = results.length === 0
    ? 'No matching products found.'
    : results.map(p => `${p.name} (${p.id})`).join('\n');

  return { content: [{ type: 'text', text }] };
}

